SELECT i.ingredient_id, COALESCE(MAX(s.name), MAX(f.name), MAX(b.name), MAX(m.name)) AS name, MAX(c.category_name) AS category, MAX(i.unit) AS unit, SUM(i.quantity) AS quantity, MIN(i.reorder_level) AS reorder_level, MAX(i.last_updated) AS last_updated, CASE WHEN SUM(i.quantity) <= 0 THEN '품절' WHEN SUM(i.quantity) < MIN(i.reorder_level) THEN '재고 부족' ELSE '정상' END AS status FROM inventory i LEFT JOIN categories c ON i.category_id = c.category_id LEFT JOIN spirits s ON i.ingredient_id = s.spirit_id AND i.category_id = 1 LEFT JOIN fruits f ON i.ingredient_id = f.fruit_id AND i.category_id = 2 LEFT JOIN beverages b ON i.ingredient_id = b.beverage_id AND i.category_id = 3 LEFT JOIN mixers m ON i.ingredient_id = m.mixer_id AND i.category_id = 4
i.category_id = #{category}
GROUP BY i.ingredient_id ORDER BY last_updated DESC LIMIT #{pageSize} OFFSET #{offset};

SELECT COUNT(DISTINCT ingredient_id)
FROM inventory
WHERE category_id = #{category};
